// Generated from mac-transport.html. Edit the .html file, then regenerate with scripts/build-shared-page.mjs.
export const MAC_TRANSPORT_HTML: string = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>Mac Transport: Startup Packet and Tracker</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap\">\n<style>\n/* Mac Transport packet + tracker. Shared tokens. Industrial neutral with a DOT-orange accent. */\n:root{\n  --bg:#f5f6f8; --surface:#ffffff; --fg:#1c2230; --muted:#5d6675; --line:#d9dde4; --soft:#eef0f3;\n  --accent:#d9541e; --accent-ink:#ffffff;\n  --ok:#2a7f4f; --warn:#b7791f; --bad:#b4332e; --idle:#8a93a2;\n  --chip-ok:#e3f3ea; --chip-warn:#fbf0d9; --chip-bad:#fae3e2; --chip-idle:#eceff3;\n  --display:\"IBM Plex Sans\",system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  --body:\"IBM Plex Sans\",system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  --mono:\"IBM Plex Mono\",ui-monospace,SFMono-Regular,Menlo,monospace;\n  color-scheme:light;\n}\n@media (prefers-color-scheme: dark){ :root:not([data-theme=\"light\"]){\n  --bg:#14181f; --surface:#1d2229; --fg:#e8ebf0; --muted:#9aa3b2; --line:#303742; --soft:#232931;\n  --accent:#f0693a; --accent-ink:#14181f;\n  --ok:#5fc48a; --warn:#e0a74a; --bad:#e8706a; --idle:#7f8899;\n  --chip-ok:#1f3a2b; --chip-warn:#3d3119; --chip-bad:#44221f; --chip-idle:#2a303a;\n  color-scheme:dark } }\n:root[data-theme=\"dark\"]{\n  --bg:#14181f; --surface:#1d2229; --fg:#e8ebf0; --muted:#9aa3b2; --line:#303742; --soft:#232931;\n  --accent:#f0693a; --accent-ink:#14181f;\n  --ok:#5fc48a; --warn:#e0a74a; --bad:#e8706a; --idle:#7f8899;\n  --chip-ok:#1f3a2b; --chip-warn:#3d3119; --chip-bad:#44221f; --chip-idle:#2a303a;\n  color-scheme:dark }\n\n*{box-sizing:border-box}\nhtml,body{margin:0}\nbody{background:var(--bg);color:var(--fg);font-family:var(--body);font-size:15px;line-height:1.5}\n.wrap{max-width:1040px;margin:0 auto;padding-block:20px 70px;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}\nh1{font-family:var(--display);font-size:28px;font-weight:600;letter-spacing:-.01em;margin:0;text-wrap:balance}\nh2{font-family:var(--display);font-size:20px;font-weight:600;margin:0 0 10px;text-wrap:balance}\nh3{font-size:15px;font-weight:600;margin:16px 0 6px}\np{margin:0 0 10px;max-width:72ch}\n.sub{color:var(--muted);margin:4px 0 0;font-size:14px}\n.eyebrow{font-family:var(--mono);font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}\na{color:var(--accent)}\n.topnav{display:flex;flex-wrap:wrap;gap:6px 16px;align-items:center;justify-content:space-between;margin-bottom:22px;padding-bottom:12px;border-bottom:1px solid var(--line)}\n.topnav .links a{font-family:var(--mono);font-size:12px;text-decoration:none;color:var(--muted);margin-left:14px}\n.topnav .links a.on{color:var(--accent)}\n.topnav .who{font-family:var(--mono);font-size:12px;color:var(--muted)}\nselect,input[type=text],input[type=date],input[type=number],input[type=password],textarea{font:inherit;color:var(--fg);background:var(--surface);border:1px solid var(--line);border-radius:4px;padding:6px 8px;min-width:0}\nselect:focus,input:focus,textarea:focus,button:focus{outline:2px solid var(--accent);outline-offset:1px}\nbutton.btn{font:inherit;font-size:13px;font-weight:500;background:var(--accent);color:var(--accent-ink);border:0;border-radius:4px;padding:7px 14px;cursor:pointer}\nbutton.btn[disabled]{opacity:.5;cursor:default}\nbutton.ghost{font:inherit;font-size:13px;background:none;border:1px solid var(--line);color:var(--fg);border-radius:4px;padding:6px 12px;cursor:pointer}\ntable{border-collapse:collapse;width:100%;font-size:14px}\nth,td{text-align:left;padding:7px 10px;border-bottom:1px solid var(--line);vertical-align:top}\nth{font-family:var(--mono);font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);font-weight:500}\ntd.n,th.n{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}\n.tbl{overflow-x:auto;border:1px solid var(--line);border-radius:6px;background:var(--surface)}\n.toast{position:fixed;left:50%;transform:translateX(-50%);bottom:calc(18px + env(safe-area-inset-bottom,0px));background:var(--fg);color:var(--bg);padding:8px 14px;border-radius:6px;font-size:13px;opacity:0;transition:opacity .2s;pointer-events:none;z-index:20}\n.toast.show{opacity:1}\n@media (prefers-reduced-motion:reduce){ .toast{transition:none} }\n\n\n\n.view{display:none} .view.on{display:block}\n.topnav .links a{cursor:pointer}\n.sync{font-family:var(--mono);font-size:12px;color:var(--muted)}\n.sync.err{color:var(--bad)}\n\n/* Packet: read top to bottom, summary first, model in the middle, decisions at the end. */\n.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px;margin:18px 0 22px}\n.tile{background:var(--surface);border:1px solid var(--line);border-radius:6px;padding:12px 14px}\n.tile .k{font-family:var(--mono);font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}\n.tile .v{font-family:var(--display);font-size:24px;font-weight:600;margin-top:4px;font-variant-numeric:tabular-nums}\n.tile .v.bad{color:var(--bad)} .tile .v.ok{color:var(--ok)} .tile .v.warn{color:var(--warn)}\n.tile .s{font-size:12px;color:var(--muted);margin-top:2px}\nsection{margin:0 0 34px}\n.findings{counter-reset:f;list-style:none;padding:0;margin:0 0 6px;display:grid;gap:10px}\n.findings li{display:grid;grid-template-columns:34px 1fr;gap:10px;max-width:78ch}\n.findings li::before{counter-increment:f;content:counter(f,decimal-leading-zero);font-family:var(--mono);color:var(--accent);font-size:13px;padding-top:2px}\n.findings b{font-weight:600;display:block}\n.two{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:16px}\n.card{background:var(--surface);border:1px solid var(--line);border-radius:6px;padding:14px 16px}\n.card h3{margin-top:0}\nul{padding-left:18px;margin:0 0 10px} li{margin-bottom:4px}\n.model{background:var(--surface);border:1px solid var(--line);border-radius:6px;padding:16px}\n.inputs{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px 18px;margin-bottom:14px}\n.inputs label{display:block;font-size:12px;color:var(--muted);font-family:var(--mono)}\n.inputs .row{display:flex;gap:8px;align-items:center}\n.inputs input[type=range]{flex:1;accent-color:var(--accent)}\n.inputs output{font-family:var(--mono);font-size:13px;min-width:66px;text-align:right;font-variant-numeric:tabular-nums}\n.out{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px}\n.out div{background:var(--soft);border-radius:4px;padding:8px 10px}\n.out .k{font-family:var(--mono);font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em}\n.out .v{font-size:18px;font-weight:600;font-variant-numeric:tabular-nums}\n.note{font-size:13px;color:var(--muted)}\n.tl{list-style:none;padding:0;margin:0;display:grid;gap:0}\n.tl li{display:grid;grid-template-columns:110px 1fr;gap:12px;padding:8px 0;border-top:1px solid var(--line)}\n.tl li:first-child{border-top:0}\n.tl .w{font-family:var(--mono);font-size:12px;color:var(--accent);padding-top:3px}\n.risk td:first-child{font-weight:500;white-space:nowrap}\n.src{font-size:13px;color:var(--muted)}\n.src li{margin-bottom:3px}\n.pill{display:inline-block;font-family:var(--mono);font-size:11px;padding:2px 7px;border-radius:10px;background:var(--chip-idle);color:var(--muted)}\n.pill.bad{background:var(--chip-bad);color:var(--bad)} .pill.warn{background:var(--chip-warn);color:var(--warn)} .pill.ok{background:var(--chip-ok);color:var(--ok)}\n@media (max-width:560px){ .tl li{grid-template-columns:1fr} .findings li{grid-template-columns:28px 1fr} }\n\n/* Tracker: sticky progress strip, nine phase sections, rows read like a dispatch sheet */\n.strip{position:sticky;top:0;z-index:5;background:var(--bg);padding-block:8px;border-bottom:1px solid var(--line);margin-bottom:22px;display:flex;flex-wrap:wrap;gap:8px 18px;align-items:center}\n\n.meter{flex:1 1 240px;min-width:0;display:flex;align-items:center;gap:12px}\n.bar{flex:1;height:8px;background:var(--chip-idle);border-radius:4px;overflow:hidden;display:flex}\n.bar span{display:block;height:100%}\n.bar .b-done{background:var(--ok)} .bar .b-prog{background:var(--warn)} .bar .b-block{background:var(--bad)}\n.count{font-family:var(--mono);font-size:13px;white-space:nowrap;font-variant-numeric:tabular-nums}\n.filters{display:flex;gap:8px;flex-wrap:wrap}\n.filters select{font-size:13px}\nsection.phase{margin-bottom:26px}\n.phase-head{display:flex;flex-wrap:wrap;align-items:baseline;gap:6px 14px;margin-bottom:8px}\n.phase-head h2{font-size:17px;margin:0}\n.phase-head .pn{font-family:var(--mono);color:var(--accent);font-size:13px}\n.phase-head .pc{font-family:var(--mono);font-size:12px;color:var(--muted);font-variant-numeric:tabular-nums}\n.phase-note{font-size:13px;color:var(--muted);margin:0 0 10px;max-width:68ch}\n.rows{border:1px solid var(--line);border-radius:6px;background:var(--surface);overflow:hidden}\n.row{display:grid;grid-template-columns:4px 1fr 150px 130px 130px 28px;gap:0 10px;align-items:center;padding:8px 10px 8px 0;border-top:1px solid var(--line)}\n.row:first-child{border-top:0}\n.row .stripe{align-self:stretch;background:var(--idle)}\n.row[data-status=\"In progress\"] .stripe{background:var(--warn)}\n.row[data-status=\"Blocked\"] .stripe{background:var(--bad)}\n.row[data-status=\"Done\"] .stripe{background:var(--ok)}\n.row[data-status=\"Done\"] .title{color:var(--muted);text-decoration:line-through}\n.title-cell{min-width:0}\n.title{cursor:pointer;background:none;border:0;padding:0;color:inherit;font:inherit;font-weight:500;text-align:left;display:flex;gap:8px;align-items:baseline}\n.title .car{font-family:var(--mono);font-size:11px;color:var(--muted);flex:none}\n.detail{display:none;font-size:13px;color:var(--muted);margin:6px 0 2px;max-width:70ch}\n.meta{display:none;font-family:var(--mono);font-size:11px;color:var(--muted);margin-top:4px}\n.row.open .detail,.row.open .meta{display:block}\n.row.open .title .car{color:var(--accent)}\n.notes{display:none;width:100%;margin-top:6px;font-size:13px;min-height:44px;resize:vertical}\n.row.open .notes{display:block}\n.row select,.row input[type=date]{width:100%;font-size:13px}\n.row select.status[data-v=\"Done\"]{background:var(--chip-ok);color:var(--ok)}\n.row select.status[data-v=\"In progress\"]{background:var(--chip-warn);color:var(--warn)}\n.row select.status[data-v=\"Blocked\"]{background:var(--chip-bad);color:var(--bad)}\n.row select.status[data-v=\"Not started\"]{background:var(--chip-idle)}\n.rm{background:none;border:0;color:var(--muted);cursor:pointer;font-size:16px;line-height:1;padding:4px;border-radius:4px}\n.rm:hover{color:var(--bad);background:var(--chip-bad)}\n.row.confirm .rm{color:var(--bad);font-family:var(--mono);font-size:11px;width:auto}\n.due.late{border-color:var(--bad);color:var(--bad)}\n.add{display:flex;gap:8px;margin-top:8px}\n.add input{flex:1}\n.empty{padding:36px 16px;text-align:center;color:var(--muted);font-size:14px}\n.empty b{display:block;color:var(--fg);font-weight:500;margin-bottom:4px}\n@media (max-width:720px){\n  .row{grid-template-columns:4px 1fr 28px;grid-template-rows:auto auto;gap:6px 10px;padding-right:6px}\n  .row .stripe{grid-row:1/3}\n  .row .title-cell{grid-column:2}\n  .row .rm{grid-column:3;grid-row:1}\n  .row .ctl{grid-column:2/4;display:flex;gap:6px}\n  .row .ctl>*{flex:1}\n}\n@media (min-width:721px){ .row .ctl{display:contents} }\n\n.row.extra .title span:last-child{font-style:normal}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <nav class=\"topnav\">\n    <div><span class=\"eyebrow\">Mac Transport LLC, Monroe NC</span></div>\n    <div class=\"links\"><a id=\"nav-packet\" href=\"#packet\">Packet</a><a id=\"nav-tracker\" href=\"#tracker\">Tracker</a><span class=\"sync\" id=\"sync\" style=\"margin-left:14px\"></span></div>\n  </nav>\n\n  <div class=\"view\" id=\"view-packet\">\n    <header style=\"margin-bottom:8px\">\n      <h1>Startup Packet</h1>\n      <p class=\"sub\">The business plan, re-run against October 2026 fuel and freight prices, with the decisions that have to be made before money moves. Prepared October 27, 2026 by Shane for Troy, Chad and Shane.</p>\n    </header>\n  <div class=\"tiles\">\n    <div class=\"tile\"><div class=\"k\">Launch capital</div><div class=\"v\">$325k to $450k</div><div class=\"s\">per the plan, new equipment</div></div>\n    <div class=\"tile\"><div class=\"k\">Diesel today</div><div class=\"v warn\">$6.28</div><div class=\"s\">US average, week of Oct 20. Plan assumed about $4.</div></div>\n    <div class=\"tile\"><div class=\"k\">Year 1, base case</div><div class=\"v bad\">about break-even</div><div class=\"s\">new truck, 100k loaded miles, today's fuel</div></div>\n    <div class=\"tile\"><div class=\"k\">Decisions open</div><div class=\"v\">7</div><div class=\"s\">none of the filings should start before these</div></div>\n  </div>\n\n  <section id=\"summary\">\n    <h2>The short version</h2>\n    <ol class=\"findings\">\n      <li><b>The structure is right.</b> Separate LLC, manufacturer as anchor customer and lender, freight billed at market. Keep all of that.</li>\n      <li><b>The $3.00 per mile is stale.</b> It is what the manufacturer paid outsourced carriers, probably when diesel was around $3.60. Diesel is $6.28 this week. Any carrier quoting today is charging a fuel surcharge on top, so the real number to anchor on is what the manufacturer is paying right now, all in. That needs pulling from the last 90 days of freight invoices before anything else.</li>\n      <li><b>The plan's EBITDA range does not survive today's fuel.</b> The plan's fuel line ($75k to $95k) works at about $4 per gallon. At $6, one truck running 118k miles burns about $108k. Rebuilt with a fuel surcharge on the revenue side and real debt service, the base case lands near zero, not $20k to $70k.</li>\n      <li><b>Used equipment flips the base case positive.</b> Dropping equipment cost from $280k to about $160k cuts debt service by roughly $25k a year. That is the difference between a small loss and a small profit at the same miles.</li>\n      <li><b>The company freight alone cannot carry the truck.</b> At 60k loaded company miles with mostly empty returns, the truck loses six figures. Reloads are not a nice-to-have; they are half the revenue. That is Troy and Chad's job and it decides whether this works.</li>\n      <li><b>New authority has a hidden cost beyond the premium.</b> Brokers discount or refuse carriers with authority under 90 days to a year. The first year of reload sourcing will be at worse rates than the market average. Running under an established carrier or a dedicated contract for year one is worth a serious look.</li>\n    </ol>\n  </section>\n\n  <section id=\"plan\">\n    <h2>What the plan says, and what we know</h2>\n    <div class=\"two\">\n      <div class=\"card\">\n        <h3>From the plan</h3>\n        <ul>\n          <li>One new sleeper tractor, one 53 foot dry van, one hired driver.</li>\n          <li>Average shipment about 600 miles. 25 percent under 300, 50 percent 300 to 700, 25 percent over 700.</li>\n          <li>Lanes: SC, NC, GA, TN, AL, OH, KY, IN, plus NE.</li>\n          <li>Current outsourced spend about $3.00 per mile.</li>\n          <li>Target 110k to 130k productive miles a year.</li>\n          <li>Costs: driver $80k to $95k, fuel $75k to $95k, insurance $35k to $50k, equipment $35k to $50k, maintenance $15k to $25k, admin $15k to $30k.</li>\n        </ul>\n      </div>\n      <div class=\"card\">\n        <h3>What is missing</h3>\n        <ul>\n          <li>Annual load count and loaded miles from the manufacturer. The plan never says how far short of 110k the company freight falls.</li>\n          <li>Whether $3.00 is linehaul only or includes fuel surcharge, and when it was measured.</li>\n          <li>Loaded versus empty miles. Revenue per total mile is what pays the bills, and empty miles cost the same fuel and driver time.</li>\n          <li>Debt terms. $35k to $50k a year on $225k to $295k of new iron implies a large down payment or a term past five years.</li>\n          <li>Who does dispatch day to day, and who is on call when the truck breaks down in Kentucky at 2am.</li>\n        </ul>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"model\">\n    <h2>The numbers, rebuilt</h2>\n    <p>Revenue is modeled as linehaul plus a fuel surcharge, the way freight is actually priced. The surcharge is the standard formula: (diesel price minus a $1.25 base) divided by 6.5 mpg. At $6.00 diesel that is about $0.73 per loaded mile on top of linehaul. Company freight uses a $2.65 linehaul, which is what reproduces the plan's $3.00 all-in at $3.60 diesel. Broker reloads use $2.10, which is the October 2026 DAT dry van spot average of $2.26 with a new-carrier haircut. Costs: fuel at 6.5 mpg, driver at $0.70 per mile with a $65k floor and 12 percent burden, insurance $42k, maintenance and tires $0.16 per mile, permits, ELD, software and accounting $22k, and equipment financed at 15 percent down, 9 percent, 60 months.</p>\n\n    <div class=\"tbl\" style=\"margin-bottom:14px\"><table>\n      <thead><tr><th>Scenario</th><th class=\"n\">Loaded mi</th><th class=\"n\">Total mi</th><th class=\"n\">Revenue</th><th class=\"n\">Costs</th><th class=\"n\">Result</th><th class=\"n\">Cost / mi</th></tr></thead>\n      <tbody>\n        <tr><td>A. Company freight only, mostly empty returns, new truck</td><td class=\"n\">60,000</td><td class=\"n\">109,000</td><td class=\"n\">$203k</td><td class=\"n\">$327k</td><td class=\"n\" style=\"color:var(--bad)\">($124k)</td><td class=\"n\">$3.00</td></tr>\n        <tr><td>B. Base: 60k company + 40k reloads, 15% empty, new truck</td><td class=\"n\">100,000</td><td class=\"n\">118,000</td><td class=\"n\">$316k</td><td class=\"n\">$343k</td><td class=\"n\" style=\"color:var(--bad)\">($27k)</td><td class=\"n\">$2.92</td></tr>\n        <tr><td>B. Same miles, used truck ($160k equipment)</td><td class=\"n\">100,000</td><td class=\"n\">118,000</td><td class=\"n\">$316k</td><td class=\"n\">$318k</td><td class=\"n\">($1k)</td><td class=\"n\">$2.70</td></tr>\n        <tr><td>C. Strong: 65k company + 50k reloads, 10% empty, new truck</td><td class=\"n\">115,000</td><td class=\"n\">128,000</td><td class=\"n\">$361k</td><td class=\"n\">$362k</td><td class=\"n\">($1k)</td><td class=\"n\">$2.83</td></tr>\n        <tr><td>C. Same miles, used truck</td><td class=\"n\">115,000</td><td class=\"n\">128,000</td><td class=\"n\">$361k</td><td class=\"n\">$336k</td><td class=\"n\" style=\"color:var(--ok)\">$25k</td><td class=\"n\">$2.63</td></tr>\n      </tbody>\n    </table></div>\n    <p class=\"note\">Result is before owner draws, income tax and the interest portion already inside debt service. The plan's own case (110k loaded miles, zero empty, $3.00 flat, $4 diesel) produces about $42k on these same cost lines, which is where its $20k to $70k range comes from.</p>\n\n    <h3>Run your own numbers</h3>\n    <div class=\"model\">\n      <div class=\"inputs\">\n        <div><label for=\"i-lc\">Company loaded miles</label><div class=\"row\"><input type=\"range\" id=\"i-lc\" min=\"20000\" max=\"110000\" step=\"5000\" value=\"60000\"><output for=\"i-lc\">60,000</output></div></div>\n        <div><label for=\"i-lb\">Reload (broker) loaded miles</label><div class=\"row\"><input type=\"range\" id=\"i-lb\" min=\"0\" max=\"80000\" step=\"5000\" value=\"40000\"><output for=\"i-lb\">40,000</output></div></div>\n        <div><label for=\"i-empty\">Empty miles, percent of total</label><div class=\"row\"><input type=\"range\" id=\"i-empty\" min=\"0\" max=\"50\" step=\"5\" value=\"15\"><output for=\"i-empty\">15%</output></div></div>\n        <div><label for=\"i-diesel\">Diesel, $ per gallon</label><div class=\"row\"><input type=\"range\" id=\"i-diesel\" min=\"3\" max=\"7.5\" step=\"0.25\" value=\"6\"><output for=\"i-diesel\">$6.00</output></div></div>\n        <div><label for=\"i-comp\">Company linehaul, $ per loaded mile</label><div class=\"row\"><input type=\"range\" id=\"i-comp\" min=\"2\" max=\"3.5\" step=\"0.05\" value=\"2.65\"><output for=\"i-comp\">$2.65</output></div></div>\n        <div><label for=\"i-brok\">Broker linehaul, $ per loaded mile</label><div class=\"row\"><input type=\"range\" id=\"i-brok\" min=\"1.5\" max=\"3\" step=\"0.05\" value=\"2.10\"><output for=\"i-brok\">$2.10</output></div></div>\n        <div><label for=\"i-equip\">Equipment cost (tractor + trailer)</label><div class=\"row\"><input type=\"range\" id=\"i-equip\" min=\"100000\" max=\"320000\" step=\"10000\" value=\"280000\"><output for=\"i-equip\">$280,000</output></div></div>\n        <div><label for=\"i-ins\">Insurance, annual</label><div class=\"row\"><input type=\"range\" id=\"i-ins\" min=\"25000\" max=\"60000\" step=\"1000\" value=\"42000\"><output for=\"i-ins\">$42,000</output></div></div>\n        <div><label for=\"i-drv\">Driver, $ per mile</label><div class=\"row\"><input type=\"range\" id=\"i-drv\" min=\"0.5\" max=\"0.9\" step=\"0.01\" value=\"0.70\"><output for=\"i-drv\">$0.70</output></div></div>\n      </div>\n      <div class=\"out\">\n        <div><div class=\"k\">Total miles</div><div class=\"v\" id=\"o-total\"></div></div>\n        <div><div class=\"k\">Revenue</div><div class=\"v\" id=\"o-rev\"></div></div>\n        <div><div class=\"k\">Fuel</div><div class=\"v\" id=\"o-fuel\"></div></div>\n        <div><div class=\"k\">Driver</div><div class=\"v\" id=\"o-drv\"></div></div>\n        <div><div class=\"k\">Debt service</div><div class=\"v\" id=\"o-debt\"></div></div>\n        <div><div class=\"k\">All costs</div><div class=\"v\" id=\"o-costs\"></div></div>\n        <div><div class=\"k\">Year 1 result</div><div class=\"v\" id=\"o-ebit\"></div></div>\n        <div><div class=\"k\">Rev / total mi</div><div class=\"v\" id=\"o-rpm\"></div></div>\n        <div><div class=\"k\">Cost / total mi</div><div class=\"v\" id=\"o-cpm\"></div></div>\n        <div><div class=\"k\">Fuel surcharge</div><div class=\"v\" id=\"o-fsc\"></div></div>\n      </div>\n      <p class=\"note\" style=\"margin:10px 0 0\">Fixed assumptions: 6.5 mpg, $65k driver floor, 12% payroll burden, $0.16 per mile maintenance and tires, $22k permits and admin, 15% down at 9% over 60 months.</p>\n    </div>\n  </section>\n\n  <section id=\"capital\">\n    <h2>Capital: new versus used</h2>\n    <div class=\"tbl\"><table>\n      <thead><tr><th>Line</th><th class=\"n\">New (plan)</th><th class=\"n\">Used, 2 to 3 years old</th></tr></thead>\n      <tbody>\n        <tr><td>Tractor</td><td class=\"n\">$180k to $230k</td><td class=\"n\">$90k to $130k</td></tr>\n        <tr><td>53 foot dry van</td><td class=\"n\">$45k to $65k</td><td class=\"n\">$25k to $40k</td></tr>\n        <tr><td>Insurance, year one</td><td class=\"n\">$28k to $55k</td><td class=\"n\">$28k to $55k</td></tr>\n        <tr><td>Licensing, permits, ELD, setup</td><td class=\"n\">$5k to $10k</td><td class=\"n\">$5k to $10k</td></tr>\n        <tr><td>Working capital reserve</td><td class=\"n\">$75k to $150k</td><td class=\"n\">$75k to $150k</td></tr>\n        <tr><td><b>Launch capital</b></td><td class=\"n\"><b>$325k to $450k</b></td><td class=\"n\"><b>$225k to $385k</b></td></tr>\n        <tr><td>Annual debt service (15% down, 9%, 60 mo)</td><td class=\"n\">$48k to $63k</td><td class=\"n\">$24k to $36k</td></tr>\n      </tbody>\n    </table></div>\n    <p class=\"note\" style=\"margin-top:8px\">A used tractor carries more maintenance risk and a shorter warranty, which is why the model keeps maintenance at $0.16 per mile either way and why the working capital reserve does not shrink. Fuel economy on a 2023 to 2024 Cascadia or T680 is close enough to new that the mpg assumption holds.</p>\n  </section>\n\n  <section id=\"authority\">\n    <h2>Authority and insurance: three ways in</h2>\n    <div class=\"two\">\n      <div class=\"card\">\n        <h3>1. Own authority from day one <span class=\"pill warn\">plan as written</span></h3>\n        <ul>\n          <li>USDOT, MC, BOC-3, UCR, insurance filings, 21 day protest period. Realistic time to active authority: 4 to 8 weeks after the LLC exists.</li>\n          <li>New authority insurance: $28k to $55k, often more with a driver under 30 or without two years verifiable OTR.</li>\n          <li>New Entrant Safety Audit inside 12 months. Fail it and the authority is revoked.</li>\n          <li>Brokers routinely require 90 days to 12 months of active authority. Reload rates in year one run below the spot average.</li>\n          <li>Full control, full margin, and the asset the partners actually want to build.</li>\n        </ul>\n      </div>\n      <div class=\"card\">\n        <h3>2. Lease onto an established carrier for year one <span class=\"pill\">lower risk</span></h3>\n        <ul>\n          <li>Mac Transport owns the truck and employs the driver; it runs under the carrier's MC and insurance for a percentage (typically 10 to 25 percent of linehaul) or a flat weekly fee.</li>\n          <li>Insurance drops to physical damage, bobtail and occupational accident. Broker access is immediate at the carrier's rates.</li>\n          <li>The manufacturer's freight can still be tendered to that carrier with Mac Transport's truck assigned to it.</li>\n          <li>Proves utilization, driver, and dispatch before taking on the compliance load. Convert to own authority in year two with a track record.</li>\n        </ul>\n      </div>\n      <div class=\"card\">\n        <h3>3. Dedicated contract carrier, no truck <span class=\"pill\">test only</span></h3>\n        <ul>\n          <li>Contract one carrier to a dedicated lane set at a fixed rate for 6 months. No capital at risk.</li>\n          <li>Tells you the true all-in cost of the company freight at today's fuel, which is the number the plan is missing.</li>\n          <li>Builds nothing, but costs nothing beyond what the manufacturer already spends.</li>\n        </ul>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"lanes\">\n    <h2>Lanes and what each state needs</h2>\n    <div class=\"tbl\"><table>\n      <thead><tr><th>State</th><th>Role in the network</th><th>Registrations beyond IRP and IFTA</th></tr></thead>\n      <tbody>\n        <tr><td>NC</td><td>Base. Monroe outbound.</td><td>IRP base plate and IFTA license through NCDMV and NCDOR. Door markings. No intrastate authority needed for interstate freight.</td></tr>\n        <tr><td>SC</td><td>Short haul, Charlotte metro spillover.</td><td>None beyond IRP and IFTA.</td></tr>\n        <tr><td>GA</td><td>Regional, Atlanta reload market is deep.</td><td>None beyond IRP and IFTA.</td></tr>\n        <tr><td>TN</td><td>Regional, Nashville and Memphis are strong reload sources.</td><td>None beyond IRP and IFTA.</td></tr>\n        <tr><td>AL</td><td>Regional, automotive and industrial reloads.</td><td>None beyond IRP and IFTA.</td></tr>\n        <tr><td>KY</td><td>Long haul corridor to OH and IN.</td><td>KYU weight distance tax number. Free, quarterly filing, required over 59,999 lbs.</td></tr>\n        <tr><td>OH, IN</td><td>Long haul, Midwest reloads back to the Southeast.</td><td>None beyond IRP and IFTA.</td></tr>\n        <tr><td>NE</td><td>Occasional long haul.</td><td>None beyond IRP and IFTA. 1,100 miles one way; only worth it with a confirmed reload.</td></tr>\n      </tbody>\n    </table></div>\n    <p class=\"note\" style=\"margin-top:8px\">NY, NM and OR weight distance taxes only apply if lanes expand there. Oversize and overweight permits do not apply to a dry van at legal weight.</p>\n  </section>\n\n  <section id=\"timeline\">\n    <h2>Timeline to first loaded mile</h2>\n    <p>Assumes the seven decisions are made in week 0 and the partners go the own-authority route. Leasing on removes weeks 3 to 8 and most of the insurance work.</p>\n    <ul class=\"tl\">\n      <li><span class=\"w\">Week 0</span><span>Decisions made. Freight volume pulled from manufacturer invoices. Operating agreement drafted.</span></li>\n      <li><span class=\"w\">Week 1</span><span>LLC filed, EIN issued, bank account opened. Insurance quotes requested with a candidate VIN. Driver search opens.</span></li>\n      <li><span class=\"w\">Week 2</span><span>USDOT and MC applications filed. BOC-3 filed. Clearinghouse employer account. Equipment financing application in.</span></li>\n      <li><span class=\"w\">Weeks 3 to 5</span><span>Protest period running. Insurance bound and filed with FMCSA. Equipment purchased, 2290 filed, IRP and IFTA applications in. ELD ordered.</span></li>\n      <li><span class=\"w\">Weeks 5 to 7</span><span>Authority active. Driver hired, DQ file built, drug test and Clearinghouse query clear. Plates and decals received. Truck marked and inspected.</span></li>\n      <li><span class=\"w\">Week 8</span><span>First company load. Broker packet circulating. Load board accounts live.</span></li>\n      <li><span class=\"w\">Months 3 to 12</span><span>New Entrant Safety Audit. Quarterly IFTA and KYU. Monthly cost per mile review. Decide on truck two only after 6 months of real numbers.</span></li>\n    </ul>\n  </section>\n\n  <section id=\"risks\">\n    <h2>Risks, ranked</h2>\n    <div class=\"tbl\"><table class=\"risk\">\n      <thead><tr><th>Risk</th><th>What it does to the numbers</th><th>Mitigation</th></tr></thead>\n      <tbody>\n        <tr><td>Under-utilization</td><td>Every 10k loaded miles short is about $28k of revenue gone against mostly fixed cost.</td><td>Confirm company volume before buying. Lease on or contract for year one. Reload plan owned by Troy and Chad with a weekly empty-mile target.</td></tr>\n        <tr><td>Fuel at $6+</td><td>Fuel is now the largest line, above the driver. A $1 move in diesel is about $18k a year at 118k miles.</td><td>Fuel surcharge in every rate, including the manufacturer's. Fuel card discounts. Model fuel monthly, not annually.</td></tr>\n        <tr><td>Driver turnover</td><td>A parked truck still costs about $9k a month in debt, insurance and admin.</td><td>Pay at or above market, predictable home time, a second vetted driver in the pipeline before you need one.</td></tr>\n        <tr><td>Insurance increase at renewal</td><td>Year two premiums can jump 20 to 40 percent after any claim.</td><td>Dashcam, clean MVR driver, safety program documented from day one.</td></tr>\n        <tr><td>FMCSA compliance</td><td>Failed New Entrant audit revokes authority. Out of service orders stop revenue.</td><td>Build the DQ file, drug consortium and maintenance records before the first dispatch. Treat the audit as a scheduled event.</td></tr>\n        <tr><td>Receivable timing</td><td>Broker freight pays in 30 to 45 days; fuel and driver pay weekly.</td><td>Manufacturer pays on 15 day terms. Factoring on broker freight if the reserve runs thin.</td></tr>\n        <tr><td>Operational overload</td><td>Dispatch, breakdowns and compliance land on whoever answers the phone, on top of the manufacturing business.</td><td>Name the dispatcher. Name the after-hours contact. Keep the weekly 30 minute review.</td></tr>\n      </tbody>\n    </table></div>\n  </section>\n\n  <section id=\"decisions\">\n    <h2>Decisions needed before anything is filed</h2>\n    <p>These are phase 01 in the <a href=\"#tracker\">tracker</a>. Each one changes what gets filed and bought in the phases after it.</p>\n    <ol>\n      <li>Pull the manufacturer's actual freight volume: loads, miles and all-in spend by lane, last 12 months, with the last 90 days separated out.</li>\n      <li>Own authority, lease on, or dedicated contract for year one.</li>\n      <li>New or used tractor and trailer.</li>\n      <li>Ownership split and operating agreement terms.</li>\n      <li>Intercompany loan amount, rate, term and security.</li>\n      <li>Transfer price for the manufacturer's freight, with a fuel surcharge clause.</li>\n      <li>Company name confirmed and available.</li>\n    </ol>\n  </section>\n\n  <section id=\"sources\">\n    <h2>Sources and assumptions</h2>\n    <ul class=\"src\">\n      <li>Business plan: Mac Transport LLC Business Plan and Startup Model (the PDF the partners provided).</li>\n      <li>Dry van spot linehaul $2.26 per mile, week ending October 17, 2026: <a href=\"https://www.dat.com/blog/dry-van-report-rates-hold-as-load-posts-cool-and-capacity-stays-thin\">DAT Dry Van Report</a>.</li>\n      <li>Diesel $6.276 per gallon national average, $5.984 East Coast, week of October 20, 2026: <a href=\"https://www.indexbox.io/blog/eia-weekly-fuel-update-gasoline-falls-diesel-rises-as-of-october-20-2026/\">EIA weekly update via IndexBox</a>.</li>\n      <li>Fuel surcharge formula, cost lines, financing terms and the new-carrier broker haircut are Shane's estimates and should be replaced with quotes as they come in. Insurance figures are the plan's; three real quotes replace them.</li>\n      <li>FMCSA minimum liability $750k for general freight; $1M is the practical market requirement. Cargo $100k is the common broker minimum. KYU applies over 59,999 lbs. These are current requirements as of this writing; confirm at filing.</li>\n    </ul>\n  </section>\n  </div>\n\n  <div class=\"view\" id=\"view-tracker\">\n    <header style=\"margin-bottom:14px\">\n      <h1>Startup Tracker</h1>\n      <p class=\"sub\">Everything that has to happen before the first loaded mile, in the order it has to happen. Changes save as you make them and everyone with this link sees the same list.</p>\n    </header>\n    <div class=\"strip\">\n      <div class=\"meter\">\n        <div class=\"bar\" id=\"bar\"><span class=\"b-done\" style=\"width:0\"></span><span class=\"b-prog\" style=\"width:0\"></span><span class=\"b-block\" style=\"width:0\"></span></div>\n        <div class=\"count\" id=\"count\">loading</div>\n      </div>\n      <div class=\"filters\">\n        <select id=\"f-owner\" aria-label=\"Filter by owner\"><option value=\"\">All owners</option></select>\n        <select id=\"f-status\" aria-label=\"Filter by status\"><option value=\"\">All statuses</option><option>Not started</option><option>In progress</option><option>Blocked</option><option>Done</option></select>\n      </div>\n    </div>\n    <div id=\"phases\"><div class=\"empty\"><b>Loading the checklist</b>Pulling the latest saved updates.</div></div>\n  </div>\n</div>\n<div class=\"toast\" id=\"toast\"></div>\n\n<script>\nvar TASKS=[{\"id\":\"decide-010\",\"p\":\"decide\",\"t\":\"Confirm manufacturer freight volume: loads per week, average miles, lanes\",\"d\":\"The number the whole plan depends on. Pull 12 months of outsourced freight invoices and total the loads, miles and spend by lane. This tells us how much of 110k miles the company freight actually covers.\",\"o\":\"Troy + Chad\",\"n\":10},{\"id\":\"decide-020\",\"p\":\"decide\",\"t\":\"Decide: new authority or run year one under an established carrier\",\"d\":\"New authority means the full insurance and compliance load on day one and the worst broker treatment for reloads. Leasing onto an existing carrier or a dedicated contract carrier deal proves the utilization math first. Decide before any filing.\",\"o\":\"Unassigned\",\"n\":20},{\"id\":\"decide-030\",\"p\":\"decide\",\"t\":\"Decide: new vs used tractor and trailer\",\"d\":\"A 2 to 3 year old tractor cuts launch capital by $60k to $100k. Under-utilization is the plan's primary risk, so lower fixed cost is the hedge.\",\"o\":\"Unassigned\",\"n\":30},{\"id\":\"decide-040\",\"p\":\"decide\",\"t\":\"Agree ownership split and operating agreement terms\",\"d\":\"Who owns what, who signs what, how profit and losses flow, what happens if someone leaves. Written before the LLC is filed.\",\"o\":\"All three\",\"n\":40},{\"id\":\"decide-050\",\"p\":\"decide\",\"t\":\"Set intercompany loan terms: amount, rate, term, security\",\"d\":\"Manufacturer is the startup lender. Needs an arm's length rate and a written note so the two companies stay separate for tax and liability.\",\"o\":\"Shane\",\"n\":50},{\"id\":\"decide-060\",\"p\":\"decide\",\"t\":\"Set the transfer price for manufacturer freight\",\"d\":\"Plan says bill at market, not free. Current outsourced spend is about $3.00 per mile, so that is the anchor. Put it in a written freight agreement with payment terms.\",\"o\":\"All three\",\"n\":60},{\"id\":\"decide-070\",\"p\":\"decide\",\"t\":\"Confirm company name availability in NC\",\"d\":\"Mac Transport LLC is proposed. Check the NC Secretary of State registry and the USDOT name search for conflicts.\",\"o\":\"Shane\",\"n\":70},{\"id\":\"entity-010\",\"p\":\"entity\",\"t\":\"File Articles of Organization with NC Secretary of State\",\"d\":\"Online filing. Registered agent and principal office in Monroe. Needs the agreed name and member list.\",\"o\":\"Shane\",\"n\":10},{\"id\":\"entity-020\",\"p\":\"entity\",\"t\":\"Get the EIN from the IRS\",\"d\":\"Free, same day online once the LLC is filed. Everything downstream (bank, DOT, insurance, payroll) wants it.\",\"o\":\"Shane\",\"n\":20},{\"id\":\"entity-030\",\"p\":\"entity\",\"t\":\"Sign the operating agreement\",\"d\":\"Finalized version of the terms agreed in phase 01.\",\"o\":\"All three\",\"n\":30},{\"id\":\"entity-040\",\"p\":\"entity\",\"t\":\"Open the business checking account and card\",\"d\":\"Separate account, no commingling with the manufacturer. Bring articles, EIN letter, operating agreement.\",\"o\":\"Shane\",\"n\":40},{\"id\":\"entity-050\",\"p\":\"entity\",\"t\":\"Set up the accounting ledger and chart of accounts\",\"d\":\"QuickBooks or similar. Chart of accounts built around cost per mile: fuel, driver, insurance, equipment, maintenance, permits, admin.\",\"o\":\"Shane\",\"n\":50},{\"id\":\"entity-060\",\"p\":\"entity\",\"t\":\"Register with NC Department of Revenue\",\"d\":\"Withholding for the driver's payroll. Sales and use if any taxable purchases need it.\",\"o\":\"Shane\",\"n\":60},{\"id\":\"entity-070\",\"p\":\"entity\",\"t\":\"Check Monroe and Union County business license requirements\",\"d\":\"Usually light for a carrier, but confirm before the first invoice.\",\"o\":\"Shane\",\"n\":70},{\"id\":\"authority-010\",\"p\":\"authority\",\"t\":\"Register the USDOT number (FMCSA Unified Registration, MCS-150)\",\"d\":\"Needs EIN, company officer, fleet size, cargo type. Free. Do this before the MC application.\",\"o\":\"Unassigned\",\"n\":10},{\"id\":\"authority-020\",\"p\":\"authority\",\"t\":\"Apply for MC operating authority (OP-1, interstate for-hire property)\",\"d\":\"$300 filing fee per authority type. Starts the 21 day protest period. Needs the USDOT number.\",\"o\":\"Unassigned\",\"n\":20},{\"id\":\"authority-030\",\"p\":\"authority\",\"t\":\"File the BOC-3 process agent designation\",\"d\":\"Done through a process agent company, usually $20 to $50, covers all states. Required before authority activates.\",\"o\":\"Unassigned\",\"n\":30},{\"id\":\"authority-040\",\"p\":\"authority\",\"t\":\"Unified Carrier Registration (UCR)\",\"d\":\"Annual registration, fee by fleet size. Register for the current year and calendar the renewal.\",\"o\":\"Shane\",\"n\":40},{\"id\":\"authority-050\",\"p\":\"authority\",\"t\":\"Get insurance filings to FMCSA and confirm authority is active\",\"d\":\"Insurer files BMC-91X (liability) directly with FMCSA. Authority goes active after the protest period and the filings. Check the SAFER record.\",\"o\":\"Unassigned\",\"n\":50},{\"id\":\"authority-060\",\"p\":\"authority\",\"t\":\"Enroll in the FMCSA Drug and Alcohol Clearinghouse (employer account)\",\"d\":\"Required before hiring. Needed for the pre-employment query and annual queries.\",\"o\":\"Unassigned\",\"n\":60},{\"id\":\"authority-070\",\"p\":\"authority\",\"t\":\"Prepare for the New Entrant Safety Audit\",\"d\":\"Happens within the first 12 months. Auditors want the driver qualification file, drug testing records, HOS records, maintenance records and the accident register. Build these from day one.\",\"o\":\"Unassigned\",\"n\":70},{\"id\":\"insurance-010\",\"p\":\"insurance\",\"t\":\"Get three or more quotes for primary auto liability\",\"d\":\"FMCSA minimum is $750k; $1M is what brokers and the manufacturer will want. New authority pricing is the plan's $28k to $55k. Quotes want a VIN, driver MVR and the lane map.\",\"o\":\"Unassigned\",\"n\":10},{\"id\":\"insurance-020\",\"p\":\"insurance\",\"t\":\"Motor truck cargo coverage\",\"d\":\"$100k is the usual broker minimum. Confirm the manufacturer's own requirement for its freight.\",\"o\":\"Unassigned\",\"n\":20},{\"id\":\"insurance-030\",\"p\":\"insurance\",\"t\":\"Physical damage on tractor and trailer\",\"d\":\"The lender will require it. Quote with the liability package.\",\"o\":\"Unassigned\",\"n\":30},{\"id\":\"insurance-040\",\"p\":\"insurance\",\"t\":\"General liability, bobtail and non-trucking liability\",\"d\":\"Brokers often ask for GL. Bobtail matters only if the truck ever runs under someone else's authority.\",\"o\":\"Unassigned\",\"n\":40},{\"id\":\"insurance-050\",\"p\":\"insurance\",\"t\":\"Workers comp and occupational accident for the driver\",\"d\":\"NC requires workers comp at three or more employees, but a single driver is still the biggest injury exposure the company has. Price it either way.\",\"o\":\"Shane\",\"n\":50},{\"id\":\"insurance-060\",\"p\":\"insurance\",\"t\":\"Bind coverage and set up the certificate of insurance process\",\"d\":\"Brokers and the manufacturer will each want a COI naming them. Make issuing one a two minute task.\",\"o\":\"Unassigned\",\"n\":60},{\"id\":\"state-010\",\"p\":\"state\",\"t\":\"IRP apportioned plates through NCDMV\",\"d\":\"Lists every state the truck will run. Needs title, 2290 proof, insurance and the USDOT number. Fees are split by miles per state.\",\"o\":\"Unassigned\",\"n\":10},{\"id\":\"state-020\",\"p\":\"state\",\"t\":\"IFTA license and decals through NCDOR\",\"d\":\"One fuel tax account for all states. Quarterly returns. The ELD mileage by state feeds this.\",\"o\":\"Shane\",\"n\":20},{\"id\":\"state-030\",\"p\":\"state\",\"t\":\"Heavy Vehicle Use Tax, Form 2290\",\"d\":\"File after the truck is purchased and before IRP. About $550 a year for a tractor over 75,000 lbs.\",\"o\":\"Shane\",\"n\":30},{\"id\":\"state-040\",\"p\":\"state\",\"t\":\"Kentucky KYU weight distance tax number\",\"d\":\"KY is on the lane map. KYU is free to register and files quarterly. NY and NM only matter if lanes change.\",\"o\":\"Shane\",\"n\":40},{\"id\":\"state-050\",\"p\":\"state\",\"t\":\"Check NC intrastate needs and oversize or overweight permits\",\"d\":\"Dry van at legal weight should not need OS/OW. Confirm nothing in the manufacturer's freight runs heavy.\",\"o\":\"Unassigned\",\"n\":50},{\"id\":\"state-060\",\"p\":\"state\",\"t\":\"Build the renewal calendar\",\"d\":\"UCR annual, 2290 annual, IFTA quarterly, KYU quarterly, IRP annual, insurance renewal, annual DOT inspection, driver medical card expiry.\",\"o\":\"Shane\",\"n\":60},{\"id\":\"equipment-010\",\"p\":\"equipment\",\"t\":\"Spec and quote the tractor\",\"d\":\"Candidates: Freightliner Cascadia, Kenworth T680, Peterbilt 579, sleeper. Depends on the new vs used decision in phase 01. Get a VIN into the insurance quotes early.\",\"o\":\"Unassigned\",\"n\":10},{\"id\":\"equipment-020\",\"p\":\"equipment\",\"t\":\"Arrange equipment financing or lease\",\"d\":\"Needs the LLC, EIN and bank account open. Expect personal guarantees on a new entity. Compare dealer financing, bank and lease.\",\"o\":\"Shane\",\"n\":20},{\"id\":\"equipment-030\",\"p\":\"equipment\",\"t\":\"Quote and buy the 53 foot dry van trailer\",\"d\":\"Plan budgets $45k to $65k new. Used is often a better deal than a used tractor.\",\"o\":\"Unassigned\",\"n\":30},{\"id\":\"equipment-040\",\"p\":\"equipment\",\"t\":\"Choose and install the ELD\",\"d\":\"Must be on the FMCSA registered device list. Motive and Samsara are the common picks. Subscription feeds HOS, IFTA mileage and dispatch.\",\"o\":\"Shane\",\"n\":40},{\"id\":\"equipment-050\",\"p\":\"equipment\",\"t\":\"Dashcam and telematics decision\",\"d\":\"Forward facing camera lowers insurance in some programs and settles accident disputes. Decide with the ELD choice.\",\"o\":\"Unassigned\",\"n\":50},{\"id\":\"equipment-060\",\"p\":\"equipment\",\"t\":\"Fuel card with network discounts\",\"d\":\"Pilot, Love's, TA programs through a card provider. Fuel is $75k to $95k a year, so a few cents a gallon matters.\",\"o\":\"Shane\",\"n\":60},{\"id\":\"equipment-070\",\"p\":\"equipment\",\"t\":\"Title, register and mark the truck\",\"d\":\"Plate ties to IRP. Door markings: company name and USDOT number, 2 inch letters, both sides.\",\"o\":\"Unassigned\",\"n\":70},{\"id\":\"equipment-080\",\"p\":\"equipment\",\"t\":\"Maintenance plan and records system\",\"d\":\"Preventive maintenance schedule, annual DOT inspection, driver vehicle inspection reports kept 3 months. Auditors check this.\",\"o\":\"Unassigned\",\"n\":80},{\"id\":\"driver-010\",\"p\":\"driver\",\"t\":\"Define driver pay, benefits and home time\",\"d\":\"Per mile, percent of load, or salary. Plan budgets $80k to $95k all in. Home time policy decides who you can hire.\",\"o\":\"Unassigned\",\"n\":10},{\"id\":\"driver-020\",\"p\":\"driver\",\"t\":\"Recruit and hire the driver\",\"d\":\"CDL-A, clean MVR, two or more years OTR, dry van experience. Start before the authority is active so the driver is ready when the truck is.\",\"o\":\"Unassigned\",\"n\":20},{\"id\":\"driver-030\",\"p\":\"driver\",\"t\":\"Build the driver qualification file\",\"d\":\"Application, MVR, three year employment verification, road test certificate, medical card, CDL copy. Required before the first dispatch.\",\"o\":\"Unassigned\",\"n\":30},{\"id\":\"driver-040\",\"p\":\"driver\",\"t\":\"Clearinghouse pre-employment query\",\"d\":\"Full query before the driver operates, then annual limited queries. Needs the driver's consent in the Clearinghouse.\",\"o\":\"Unassigned\",\"n\":40},{\"id\":\"driver-050\",\"p\":\"driver\",\"t\":\"Pre-employment drug test and random testing consortium\",\"d\":\"Negative pre-employment test on file before driving. Join a consortium for random testing (required even with one driver).\",\"o\":\"Unassigned\",\"n\":50},{\"id\":\"driver-060\",\"p\":\"driver\",\"t\":\"Written safety policies\",\"d\":\"Hours of service, drug and alcohol policy (driver signs it), accident procedure, cargo securement, cell phone. Short and signed.\",\"o\":\"Unassigned\",\"n\":60},{\"id\":\"driver-070\",\"p\":\"driver\",\"t\":\"Payroll setup for a W-2 driver\",\"d\":\"Gusto or similar. Per diem handling, withholding, and the settlement sheet feeds into it.\",\"o\":\"Shane\",\"n\":70},{\"id\":\"ops-010\",\"p\":\"ops\",\"t\":\"Pick or build the dispatch and TMS tool\",\"d\":\"Loads, rate confirmations, BOLs, invoices, driver settlements. Off the shelf is fine for one truck; decide what Troy and Chad actually want to touch.\",\"o\":\"Shane\",\"n\":10},{\"id\":\"ops-020\",\"p\":\"ops\",\"t\":\"Set up load board accounts\",\"d\":\"DAT and Truckstop for backhaul sourcing out of TN, OH/KY, AL/GA. Needs active authority to post or book.\",\"o\":\"Troy + Chad\",\"n\":20},{\"id\":\"ops-030\",\"p\":\"ops\",\"t\":\"Build the broker carrier packet\",\"d\":\"W-9, COI, authority letter, operating authority docs, references. Every broker asks for the same packet; have it as one PDF.\",\"o\":\"Shane\",\"n\":30},{\"id\":\"ops-040\",\"p\":\"ops\",\"t\":\"Invoicing and AR process, factoring vs direct billing\",\"d\":\"Manufacturer freight can be billed direct on short terms. Broker freight often runs 30 to 45 days; decide if factoring is worth 2 to 3 percent for cash flow.\",\"o\":\"Shane\",\"n\":40},{\"id\":\"ops-050\",\"p\":\"ops\",\"t\":\"Driver settlement process and pay schedule\",\"d\":\"Weekly settlement from completed loads and ELD miles. Feeds payroll.\",\"o\":\"Shane\",\"n\":50},{\"id\":\"ops-060\",\"p\":\"ops\",\"t\":\"Lane and reload plan\",\"d\":\"Treat Monroe outbound as a network. Map the top reload partners by destination region and set a target empty mile percentage.\",\"o\":\"Troy + Chad\",\"n\":60},{\"id\":\"ops-070\",\"p\":\"ops\",\"t\":\"Company email, phone, document storage, shared calendar\",\"d\":\"One domain, one shared drive for compliance records, one calendar for renewals and audits.\",\"o\":\"Shane\",\"n\":70},{\"id\":\"ops-080\",\"p\":\"ops\",\"t\":\"Weekly ops cadence\",\"d\":\"Thirty minutes a week: loads completed, loaded vs empty miles, revenue per mile, open issues. Cost per mile is the number that matters.\",\"o\":\"All three\",\"n\":80},{\"id\":\"finance-010\",\"p\":\"finance\",\"t\":\"Finalize the launch budget\",\"d\":\"Plan range is $325k to $450k. Lock the actual number once equipment and insurance quotes are in.\",\"o\":\"Shane\",\"n\":10},{\"id\":\"finance-020\",\"p\":\"finance\",\"t\":\"Draft and sign the intercompany loan agreement\",\"d\":\"Promissory note from the manufacturer to Mac Transport. Terms from phase 01. Lawyer or CPA reviews it.\",\"o\":\"Shane\",\"n\":20},{\"id\":\"finance-030\",\"p\":\"finance\",\"t\":\"Fund the working capital reserve\",\"d\":\"Plan says $75k to $150k. Covers fuel, driver pay and insurance before receivables start arriving.\",\"o\":\"Shane\",\"n\":30},{\"id\":\"finance-040\",\"p\":\"finance\",\"t\":\"Build the per-mile financial model\",\"d\":\"Loaded vs empty miles, company rate vs broker rate, real debt service, insurance and fuel sensitivity. Replaces the plan's single $3.00 per mile assumption.\",\"o\":\"Shane\",\"n\":40},{\"id\":\"finance-050\",\"p\":\"finance\",\"t\":\"Monthly P&L and cost per mile report\",\"d\":\"Same format every month. Revenue per loaded mile, cost per total mile, utilization.\",\"o\":\"Shane\",\"n\":50},{\"id\":\"finance-060\",\"p\":\"finance\",\"t\":\"Tax plan with a CPA\",\"d\":\"Entity tax election, depreciation on the equipment, driver per diem, and how the intercompany loan and freight billing are treated.\",\"o\":\"Shane\",\"n\":60}];\n(function(){\n  // ---------- shared state sync (same contract as the other /p pages) ----------\n  var slug=location.pathname.replace(/\\/+$/,\"\").split(\"/\").pop();\n  var API=\"/api/p/\"+encodeURIComponent(slug)+\"/state\";\n  var syncEl=document.getElementById(\"sync\");\n  var state={},pending={},timer=null,inflight=false;\n  function setSync(t,err){syncEl.textContent=t;syncEl.className=err?\"sync err\":\"sync\"}\n  var toastT;function toast(m){var t=document.getElementById(\"toast\");t.textContent=m;t.classList.add(\"show\");clearTimeout(toastT);toastT=setTimeout(function(){t.classList.remove(\"show\")},1800)}\n  function put(k,v){pending[k]=v;state[k]=v;setSync(\"Saving...\");schedule(typeof v===\"string\"&&v.length>12?700:150)}\n  function flush(){timer=null;if(inflight){schedule(400);return}var patch=pending;pending={};if(!Object.keys(patch).length)return;inflight=true;setSync(\"Saving...\");\n    fetch(API,{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify({patch:patch})}).then(function(r){if(!r.ok)throw new Error(r.status);return r.json()}).then(function(d){state=d.state||{};setSync(\"All changes saved\")}).catch(function(){Object.keys(patch).forEach(function(k){if(!pending.hasOwnProperty(k))pending[k]=patch[k]});setSync(\"Couldn't save, retrying...\",true);schedule(4000)}).then(function(){inflight=false})}\n  function schedule(ms){if(timer)clearTimeout(timer);timer=setTimeout(flush,ms)}\n  function load(first){return fetch(API,{cache:\"no-store\"}).then(function(r){if(!r.ok)throw new Error(r.status);return r.json()}).then(function(d){var s=d.state||{};Object.keys(pending).forEach(function(k){s[k]=pending[k]});state=s;render();if(first)setSync(\"All changes saved\")}).catch(function(){if(first){render();setSync(\"Couldn't load saved updates. Check your connection and refresh.\",true)}})}\n\n  // ---------- views ----------\n  function showView(){var v=location.hash===\"#tracker\"?\"tracker\":\"packet\";document.getElementById(\"view-packet\").className=\"view\"+(v===\"packet\"?\" on\":\"\");document.getElementById(\"view-tracker\").className=\"view\"+(v===\"tracker\"?\" on\":\"\");document.getElementById(\"nav-packet\").className=v===\"packet\"?\"on\":\"\";document.getElementById(\"nav-tracker\").className=v===\"tracker\"?\"on\":\"\";window.scrollTo(0,0)}\n  window.addEventListener(\"hashchange\",showView);showView();\n\n  // ---------- packet model ----------\n  var ids=[\"lc\",\"lb\",\"empty\",\"diesel\",\"comp\",\"brok\",\"equip\",\"ins\",\"drv\"];\n  var fmt=function(n){return (n<0?\"($\":\"$\")+Math.round(Math.abs(n)).toLocaleString()+(n<0?\")\":\"\")};\n  var fmtK=function(n){return (n<0?\"($\":\"$\")+Math.round(Math.abs(n)/1000)+\"k\"+(n<0?\")\":\"\")};\n  function val(k){return parseFloat(document.getElementById(\"i-\"+k).value)}\n  function label(k){var v=val(k),o=document.querySelector('output[for=\"i-'+k+'\"]');o.textContent= k===\"empty\"?v+\"%\": (k===\"lc\"||k===\"lb\")?v.toLocaleString(): (k===\"equip\"||k===\"ins\")?\"$\"+v.toLocaleString(): \"$\"+v.toFixed(2)}\n  function runModel(){ids.forEach(label);\n    var lc=val(\"lc\"),lb=val(\"lb\"),empty=val(\"empty\")/100,diesel=val(\"diesel\"),comp=val(\"comp\"),brok=val(\"brok\"),equip=val(\"equip\"),ins=val(\"ins\"),drv=val(\"drv\");\n    var mpg=6.5,fsc=Math.max(0,(diesel-1.25)/6.5),loaded=lc+lb,total=loaded/(1-empty);\n    var rev=lc*(comp+fsc)+lb*(brok+fsc),fuel=total/mpg*diesel,driver=Math.max(total*drv,65000)*1.12;\n    var Pn=equip*0.85,r=0.09/12,pay=Pn*r/(1-Math.pow(1+r,-60)),debt=pay*12,maint=total*0.16,admin=22000;\n    var costs=fuel+driver+ins+debt+maint+admin,ebit=rev-costs;\n    var s=function(id,v){document.getElementById(id).textContent=v};\n    s(\"o-total\",Math.round(total).toLocaleString());s(\"o-rev\",fmtK(rev));s(\"o-fuel\",fmtK(fuel));s(\"o-drv\",fmtK(driver));s(\"o-debt\",fmtK(debt));s(\"o-costs\",fmtK(costs));\n    var e=document.getElementById(\"o-ebit\");e.textContent=fmt(ebit);e.style.color=ebit<0?\"var(--bad)\":\"var(--ok)\";\n    s(\"o-rpm\",\"$\"+(rev/total).toFixed(2));s(\"o-cpm\",\"$\"+(costs/total).toFixed(2));s(\"o-fsc\",\"$\"+fsc.toFixed(2)+\"/mi\")}\n  ids.forEach(function(k){document.getElementById(\"i-\"+k).addEventListener(\"input\",runModel)});runModel();\n\n  // ---------- tracker ----------\n  var OWNERS=[\"Unassigned\",\"Troy\",\"Chad\",\"Shane\",\"Troy + Chad\",\"All three\"];\n  var STATUSES=[\"Not started\",\"In progress\",\"Blocked\",\"Done\"];\n  var PHASES=[\n    {n:\"01\",key:\"decide\",title:\"Decisions before anything is filed\",note:\"Partner decisions. Nothing below this line should be spent until these are settled and written down.\"},\n    {n:\"02\",key:\"entity\",title:\"Entity, banking and books\",note:\"Standalone LLC with its own EIN, bank account and ledger. Nothing runs through the manufacturing company's accounts.\"},\n    {n:\"03\",key:\"authority\",title:\"Federal authority\",note:\"USDOT, MC and the filings FMCSA needs to activate the authority. Insurance filings gate activation, so phase 04 runs in parallel.\"},\n    {n:\"04\",key:\"insurance\",title:\"Insurance\",note:\"The single biggest fixed cost and the one that gates authority. Start quotes early; new-authority pricing is the plan's $28k to $55k.\"},\n    {n:\"05\",key:\"state\",title:\"State registrations and taxes\",note:\"Plates, fuel tax and the per-state permits the lane map (NC, SC, GA, TN, AL, OH, KY, IN) actually touches.\"},\n    {n:\"06\",key:\"equipment\",title:\"Equipment\",note:\"Tractor, trailer, ELD and fuel. Insurance quotes want a VIN, financing wants the LLC and EIN.\"},\n    {n:\"07\",key:\"driver\",title:\"Driver, safety and compliance\",note:\"What FMCSA checks in the New Entrant audit within the first 12 months. Build the file before the first dispatch.\"},\n    {n:\"08\",key:\"ops\",title:\"Operations and back office\",note:\"Dispatch, load boards, billing, settlements. Built so Troy and Chad can run freight without touching accounting.\"},\n    {n:\"09\",key:\"finance\",title:\"Capital and finance\",note:\"Launch capitalization, the intercompany loan, and the monthly numbers that tell us whether the truck is working.\"}\n  ];\n  var $=function(s,el){return (el||document).querySelector(s)};\n  function esc(s){return String(s==null?\"\":s).replace(/[&<>\"']/g,function(c){return {\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]})}\n  function today(){var d=new Date();return d.getFullYear()+\"-\"+String(d.getMonth()+1).padStart(2,\"0\")+\"-\"+String(d.getDate()).padStart(2,\"0\")}\n  var fo=$(\"#f-owner\");OWNERS.forEach(function(o){var op=document.createElement(\"option\");op.textContent=o;fo.appendChild(op)});\n  var openIds={};try{openIds=JSON.parse(localStorage.getItem(\"mt-open\")||\"{}\")}catch(e){}\n  try{fo.value=localStorage.getItem(\"mt-fo\")||\"\";$(\"#f-status\").value=localStorage.getItem(\"mt-fs\")||\"\"}catch(e){}\n  fo.addEventListener(\"change\",function(){try{localStorage.setItem(\"mt-fo\",fo.value)}catch(e){}render()});\n  $(\"#f-status\").addEventListener(\"change\",function(){try{localStorage.setItem(\"mt-fs\",$(\"#f-status\").value)}catch(e){}render()});\n\n  // A task's live fields come from state: s-<id> status, o-<id> owner, d-<id> due, n-<id> notes.\n  // Extra tasks added on the page live in x-<phase> as a JSON list of {id,t}.\n  function extras(phase){try{var v=state[\"x-\"+phase];return v?JSON.parse(v):[]}catch(e){return []}}\n  function allTasks(){var out=[];PHASES.forEach(function(p){TASKS.filter(function(t){return t.p===p.key}).forEach(function(t){out.push(t)});extras(p.key).forEach(function(x){out.push({id:x.id,p:p.key,t:x.t,d:\"\",o:\"Unassigned\",n:9999,extra:true})})});return out}\n  function F(t){return {status:state[\"s-\"+t.id]||\"Not started\",owner:state[\"o-\"+t.id]||t.o,due:state[\"d-\"+t.id]||\"\",notes:state[\"n-\"+t.id]||\"\"}}\n  function sel(cls,opts,v,extra){var h='<select class=\"'+cls+'\" '+(extra||\"\")+' data-v=\"'+esc(v)+'\">';opts.forEach(function(o){h+='<option'+(o===v?' selected':'')+'>'+esc(o)+'</option>'});return h+'</select>'}\n\n  function render(){\n    var fOwner=fo.value,fStatus=$(\"#f-status\").value,td=today(),list=allTasks();\n    var done=0,prog=0,block=0,total=list.length;\n    list.forEach(function(t){var f=F(t);if(f.status===\"Done\")done++;else if(f.status===\"In progress\")prog++;else if(f.status===\"Blocked\")block++});\n    var b=$(\"#bar\").children,pct=function(n){return total?(100*n/total)+\"%\":\"0%\"};\n    b[0].style.width=pct(done);b[1].style.width=pct(prog);b[2].style.width=pct(block);\n    $(\"#count\").textContent=done+\" / \"+total+\" done\"+(block?\", \"+block+\" blocked\":\"\");\n    var focused=document.activeElement&&document.activeElement.classList&&document.activeElement.classList.contains(\"notes\")?document.activeElement.id:null;\n    if(focused)return;\n    var h=\"\";\n    PHASES.forEach(function(p){\n      var pl=list.filter(function(t){return t.p===p.key});\n      var pd=pl.filter(function(t){return F(t).status===\"Done\"}).length;\n      var vis=pl.filter(function(t){var f=F(t);return (!fOwner||f.owner===fOwner)&&(!fStatus||f.status===fStatus)});\n      if(!vis.length&&(fOwner||fStatus))return;\n      h+='<section class=\"phase\" data-phase=\"'+p.key+'\"><div class=\"phase-head\"><span class=\"pn\">'+p.n+'</span><h2>'+esc(p.title)+'</h2><span class=\"pc\">'+pd+' / '+pl.length+'</span></div><p class=\"phase-note\">'+esc(p.note)+'</p><div class=\"rows\">';\n      vis.forEach(function(t){var f=F(t);var late=f.due&&f.due<td&&f.status!==\"Done\";\n        h+='<div class=\"row'+(openIds[t.id]?' open':'')+(t.extra?' extra':'')+'\" data-id=\"'+esc(t.id)+'\" data-status=\"'+esc(f.status)+'\"><div class=\"stripe\"></div>'\n          +'<div class=\"title-cell\"><button class=\"title\" type=\"button\"><span class=\"car\">'+(openIds[t.id]?'&#9660;':'&#9654;')+'</span><span>'+esc(t.t)+'</span></button>'\n          +'<div class=\"detail\">'+esc(t.d||\"\")+'</div>'\n          +'<textarea class=\"notes\" id=\"n-'+esc(t.id)+'\" placeholder=\"Notes, who you called, what they said\">'+esc(f.notes)+'</textarea></div>'\n          +'<div class=\"ctl\">'+sel(\"owner\",OWNERS,f.owner,'id=\"o-'+esc(t.id)+'\" aria-label=\"Owner\"')\n          +sel(\"status\",STATUSES,f.status,'id=\"s-'+esc(t.id)+'\" aria-label=\"Status\"')\n          +'<input type=\"date\" class=\"due'+(late?' late':'')+'\" id=\"d-'+esc(t.id)+'\" value=\"'+esc(f.due)+'\" aria-label=\"Due date\"></div>'\n          +(t.extra?'<button class=\"rm\" type=\"button\" title=\"Remove task\">&times;</button>':'<span></span>')+'</div>';\n      });\n      h+='</div><form class=\"add\" data-phase=\"'+p.key+'\"><input type=\"text\" id=\"add-'+p.key+'\" placeholder=\"Add a task to this phase\" maxlength=\"160\"><button class=\"btn\" type=\"submit\">Add</button></form></section>';\n    });\n    $(\"#phases\").innerHTML=h;\n  }\n\n  var noteT={};\n  document.addEventListener(\"change\",function(ev){var el=ev.target,row=el.closest(\".row\");if(!row)return;var id=row.dataset.id;\n    if(el.classList.contains(\"status\")){el.dataset.v=el.value;row.dataset.status=el.value;put(\"s-\"+id,el.value);var list=allTasks(),done=list.filter(function(t){return F(t).status===\"Done\"}).length;$(\"#count\").textContent=done+\" / \"+list.length+\" done\"}\n    else if(el.classList.contains(\"owner\")){put(\"o-\"+id,el.value)}\n    else if(el.classList.contains(\"due\")){put(\"d-\"+id,el.value)}});\n  document.addEventListener(\"input\",function(ev){var el=ev.target;if(!el.classList.contains(\"notes\"))return;var id=el.closest(\".row\").dataset.id;clearTimeout(noteT[id]);noteT[id]=setTimeout(function(){put(\"n-\"+id,el.value)},600)});\n  document.addEventListener(\"click\",function(ev){\n    var tb=ev.target.closest(\".title\");\n    if(tb){var row=tb.closest(\".row\"),id=row.dataset.id;row.classList.toggle(\"open\");if(row.classList.contains(\"open\"))openIds[id]=1;else delete openIds[id];tb.querySelector(\".car\").innerHTML=row.classList.contains(\"open\")?\"&#9660;\":\"&#9654;\";try{localStorage.setItem(\"mt-open\",JSON.stringify(openIds))}catch(e){}return}\n    var rm=ev.target.closest(\".rm\");\n    if(rm){var r=rm.closest(\".row\");if(!r.classList.contains(\"confirm\")){r.classList.add(\"confirm\");rm.textContent=\"remove?\";setTimeout(function(){r.classList.remove(\"confirm\");rm.innerHTML=\"&times;\"},3000);return}\n      var id2=r.dataset.id,phase=r.closest(\".phase\").dataset.phase;var xs=extras(phase).filter(function(x){return x.id!==id2});\n      put(\"x-\"+phase,JSON.stringify(xs));[\"s-\",\"o-\",\"d-\",\"n-\"].forEach(function(k){put(k+id2,null)});render();toast(\"Task removed\")}\n  });\n  document.addEventListener(\"submit\",function(ev){var f=ev.target.closest(\".add\");if(!f)return;ev.preventDefault();\n    var inp=f.querySelector(\"input\"),title=inp.value.trim();if(!title)return;var phase=f.dataset.phase,xs=extras(phase);\n    xs.push({id:phase+\"-x\"+Date.now().toString(36),t:title});var s=JSON.stringify(xs);if(s.length>3900){toast(\"Too many extra tasks in this phase\");return}\n    put(\"x-\"+phase,s);inp.value=\"\";render();toast(\"Task added\")});\n\n  load(true);\n  setInterval(function(){if(!document.hidden&&!inflight&&!Object.keys(pending).length)load(false)},10000);\n  document.addEventListener(\"visibilitychange\",function(){if(!document.hidden)load(false)});\n  window.addEventListener(\"beforeunload\",function(e){if(Object.keys(pending).length){flush();e.preventDefault()}});\n})();\n</script>\n</body>\n</html>\n"
